'use strict'

process.chdir(__dirname)

const cdpc = require('../index')

const cm = new cdpc()

cm.runChilds([
  {
    name: 'date',
    command: 'date',
    restart: 'count',
    restartDelay: 1000,
    restartLimit: 0,
    autoRemove: true,
    options: {
      stdio: ['ignore', 1, 2]
    }
  },
  
  {
    name : 'app',
    file: 'app1.js',
    restart: 'always',
    restartDelay: 1000,
    options: {
      stdio: ['ignore', 1, 2]
    }
  }

])

setTimeout(() => {
  console.log('检测date应用是否存在...')
  let a = cm.find('date')

  console.log(a ? a : 'null')
}, 4500)

console.log('15秒后暂停app (name=app)，并且在25秒后恢复服务...')

setTimeout(() => {
  console.log('app paused')
  cm.pause('app')
}, 15000)

setTimeout(() => {
  console.log('app resume')
  cm.resume('app')
}, 25000)

setTimeout(() => {
  console.log('测试完成，主进程退出。')
  process.exit(0)
}, 35000);

